contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to Collect _am after optionally depositing amount 'dep'.
    // We check: if Collect call does not revert and succeeds, then
    // balances[this] decreased by _am and address(this).balance increased by _am (and address(c).balance decreased by _am).
    function run(uint dep, uint _am) public payable {
        // ensure this contract has enough ETH to deposit if asked
        if (dep > 0) {
            require(address(this).balance >= dep);
            // Deposit into c as this contract
            c.Deposit{value: dep}();
        }

        // read balances before trying Collect
        uint bal_before = c.balances(address(this));
        uint c_bal_before = address(c).balance;

        bool reverted;
        // attempt Collect; it may revert depending on MinSum and balances
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint bal_after = c.balances(address(this));
        uint c_bal_after = address(c).balance;
        uint my_bal_after = address(this).balance;

        // If Collect did NOT revert, then caller's recorded balance must have decreased by exactly _am,
        // and address(c).balance must have decreased by _am, which implies this contract's balance increased by _am.
        // We express that as: not reverted => (bal_before == bal_after + _am && c_bal_before == c_bal_after + _am && my_bal_after >= _am);
        // Avoid depending on prior external funds for exact equality of my_bal_after, so we check c's balance change and balances mapping.
        assert(reverted || (bal_before == bal_after + _am && c_bal_before == c_bal_after + _am));
    }

    // allow receiving ETH when Collect sends funds back
    receive() external payable {}
}

