contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to enforce that successful Collect only happens when preconditions hold and that it
    // transfers exactly the requested amount both from recorded balance and contract balance.
    function run(uint dep, uint am, uint minSum, address logAddr) public payable {
        // allow depositing if requested
        if (dep > 0) {
            require(address(this).balance >= dep);
            c.Deposit{value: dep}();
        }

        // If needed, set MinSum and Log before initialization; these may revert if already initialized
        // We perform them as top-level calls (they may revert and abort the run call entirely).
        // To avoid revert we wrap them in try/catch style by first calling only when plausible.
        // But per constraints we may call them directly; however to keep the test widely applicable
        // we avoid calling Initialized here so SetMinSum/SetLogFile should succeed on fresh c.
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);

        // Observe pre-call values
        uint bal_before = c.balances(address(this));
        uint contract_bal_before = address(c).balance;
        uint minsum_now = c.MinSum();

        bool reverted;
        // Attempt Collect as top-level call
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call values
        uint bal_after = c.balances(address(this));
        uint contract_bal_after = address(c).balance;

        // General rule:
        // If Collect succeeded (not reverted) then the preconditions must have held
        // (bal_before >= minsum_now && bal_before >= am) and balances decreased by exactly am
        // and contract balance decreased by exactly am. If Collect reverted, nothing is required.
        assert(reverted || (bal_before >= minsum_now && bal_before >= am && bal_after + am == bal_before && contract_bal_after + am == contract_bal_before));
    }

    receive() external payable {}
}

