contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to deposit, amount to collect, minSum to set, and address to set as LogFile (can be zero)
    function run(uint depositAmt, uint collectAmt, uint minSum, address logAddr) public payable {
        // ensure test contract can send depositAmt
        require(address(this).balance >= depositAmt);

        // set MinSum and Log before initialization (allowed)
        c.SetMinSum(minSum);
        // set log file address (may be zero, but SetLogFile accepts any address)
        c.SetLogFile(logAddr);

        // record before values
        uint beforeRecorded = c.balances(address(this));
        uint beforeBalanceC = address(c).balance;

        // perform deposit (may revert if overflow, but Solidity 0.8 will revert on overflow; Deposit has explicit check too)
        bool depositReverted;
        try c.Deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // read after deposit values
        uint afterRecorded = c.balances(address(this));
        uint afterBalanceC = address(c).balance;

        // attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final recorded balance and contract balance
        uint finalRecorded = c.balances(address(this));
        uint finalBalanceC = address(c).balance;

        // General rule asserted below:
        // If Collect succeeded (did not revert) then:
        //  - before Collect, caller had at least minSum and at least collectAmt
        //  - the recorded balance decreased by exactly collectAmt
        //  - the contract's Ether balance decreased by exactly collectAmt
        // We express "Collect succeeded => preconditions held" by checking that if collect did not revert,
        // then the recorded balance just before Collect was >= minSum and >= collectAmt.
        // Note: use values we observed: afterDeposit values are the ones before Collect.

        assert(
            collectReverted || (
                // preconditions: recorded balance before collect >= MinSum and >= collectAmt
                afterRecorded >= c.MinSum() && afterRecorded >= collectAmt
                // and recorded decreased by collectAmt
                && finalRecorded + collectAmt == afterRecorded
                // and contract balance decreased by collectAmt
                && finalBalanceC + collectAmt == afterBalanceC
            )
        );
    }

    // allow receiving Ether so the test contract can be funded by external txs
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to deposit, amount to collect
    function run(uint depositAmt, uint collectAmt) public payable {
        // ensure this contract can fund the deposit
        require(address(this).balance >= depositAmt);

        // record initial observed values
        uint beforeRecorded = c.balances(address(this));
        uint beforeBalanceC = address(c).balance;

        // attempt deposit (may revert)
        bool depositReverted;
        try c.Deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // values after deposit (these are the values just before Collect)
        uint midRecorded = c.balances(address(this));
        uint midBalanceC = address(c).balance;

        // attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // values after Collect
        uint finalRecorded = c.balances(address(this));
        uint finalBalanceC = address(c).balance;

        // Assert the general invariant: if Collect succeeded then
        // (1) the recorded balance decreased by exactly collectAmt, and
        // (2) the contract's Ether balance decreased by exactly collectAmt.
        // We compare against the mid-state (state immediately before Collect).
        assert(
            collectReverted || (
                // avoid underflow in arithmetic by using addition on final side
                finalRecorded + collectAmt == midRecorded
                && finalBalanceC + collectAmt == midBalanceC
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // try a deposit then attempt Collect; parameters: deposit amount and collect amount
    function run(uint depositAmt, uint collectAmt) public payable {
        // ensure this contract can fund the deposit
        require(address(this).balance >= depositAmt);

        // record before values
        uint beforeRecorded = c.balances(address(this));
        uint beforeMin = c.MinSum();

        // attempt Deposit (may revert)
        bool depositReverted;
        try c.Deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // read mid-state recorded balance (after possible deposit)
        uint midRecorded = c.balances(address(this));

        // attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final recorded balance
        uint finalRecorded = c.balances(address(this));

        // General rule:
        // If Collect succeeded then:
        //  (A) the final recorded balance is strictly less than the recorded balance before Collect (i.e., Collect reduced the recorded balance),
        //  (B) and the Collect success implies the Collect preconditions were true at the moment of the call: midRecorded >= beforeMin and midRecorded >= collectAmt.
        // Note: We use midRecorded and beforeMin (MinSum cannot increase via public interface after initialization by this test), and avoid assuming non-reentrant behavior beyond observed balances.
        assert(
            collectReverted || (
                finalRecorded < midRecorded
                && midRecorded >= beforeMin
                && midRecorded >= collectAmt
            )
        );
    }

    // allow receiving Ether for test funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters: amount to deposit first (so there's balance) and amount to collect
    function run(uint depositAmt, uint collectAmt) public payable {
        // ensure test contract can fund the deposit
        require(address(this).balance >= depositAmt);

        // record balances before any interaction
        uint beforeRecorded = c.balances(address(this));
        uint beforeCbal = address(c).balance;

        // attempt Deposit (may revert)
        bool depositReverted;
        try c.Deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // record after-deposit (or unchanged if reverted)
        uint midRecorded = c.balances(address(this));
        uint midCbal = address(c).balance;

        // attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // record final values
        uint finalRecorded = c.balances(address(this));
        uint finalCbal = address(c).balance;

        // If Collect succeeded then:
        //  - finalRecorded == midRecorded - collectAmt
        //  - finalCbal == midCbal - collectAmt
        // Use assertions that avoid underflow by only requiring the equalities when collect succeeded.
        assert(collectReverted || (midRecorded >= collectAmt && midCbal >= collectAmt && finalRecorded == (midRecorded - collectAmt) && finalCbal == (midCbal - collectAmt)));
    }

    receive() external payable {}
}

