contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call Collect with arbitrary amount; send no Ether when invoking Collect here.
    function run(uint am) public payable {
        // record balances before
        uint beforeRecorded = c.balances(address(this));
        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterRecorded = c.balances(address(this));
        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;

        // General invariant: if Collect did not revert, then recorded balance decreased by am
        // (but only if beforeRecorded >= am and beforeRecorded >= c.MinSum()) — however the externally
        // observable condition that allows Collect to proceed is that beforeRecorded >= am and beforeRecorded >= c.MinSum().
        // We express the rule: if not reverted and the preconditions held, then recorded reduced by am and Ether moved.
        uint minSum = c.MinSum();

        bool preconds = (beforeRecorded >= am) && (beforeRecorded >= minSum);

        assert(reverted || (!reverted && preconds && afterRecorded + am == beforeRecorded && cBalanceAfter + am == cBalanceBefore && selfBalanceAfter == selfBalanceBefore + am));
    }

    receive() external payable { }
}

