contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint minSum, uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt + 1); // need some extra for safety

        // initialize contract: set MinSum and log, then mark initialized
        // SetLogFile expects an address of LogFile; we can pass address(0) since it's allowed before Initialized
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // read balance before
        uint beforeRecorded = c.balances(address(this));
        uint beforeBal = address(this).balance;
        uint beforeCbal = address(c).balance;

        // Deposit depositAmt into c from this contract
        c.Deposit{value: depositAmt}();

        // attempt to Collect collectAmt and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterRecorded = c.balances(address(this));
        uint afterBal = address(this).balance;
        uint afterCbal = address(c).balance;

        // General rule: if Collect succeeded then recorded balance decreased by collectAmt and the tester's balance increased by collectAmt and c's balance decreased by collectAmt
        assert(reverted || (beforeRecorded >= collectAmt && beforeRecorded - collectAmt == afterRecorded && afterBal == beforeBal + collectAmt && afterCbal + collectAmt == beforeCbal));
    }

    // allow receiving Ether so c.call can send to this contract
    receive() external payable {}
}

