        c.SetMinSum(_minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // deposit some ether into c from this contract (top-level state-changing call)
        // need to ensure we have balance to send
        c.Deposit{value: _deposit}();

        // read balance before collect
        uint bal_before = c.balances(address(this));
        uint contract_balance_before = address(this).balance;
        uint c_balance_before = address(c).balance;

        // attempt Collect and catch revert
        bool reverted;
        try c.Collect(_collect) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint bal_after = c.balances(address(this));
        uint contract_balance_after = address(this).balance;
        uint c_balance_after = address(c).balance;

        // General rule asserted: if Collect returned (not reverted) then
        // preconditions held (bal_before >= _minSum and bal_before >= _collect),
        // and balances decreased by exactly _collect and this contract's balance increased by _collect
        // and c's ether balance decreased by _collect. If Collect reverted then balances unchanged.
        assert(
            (
                !reverted
                ? (
                    bal_before >= _minSum && bal_before >= _collect
                    && bal_after == bal_before - _collect
                    && contract_balance_after == contract_balance_before + _collect
                    && c_balance_after + _collect == c_balance_before
                )
                : (
                    bal_after == bal_before
                    && contract_balance_after == contract_balance_before
                    && c_balance_after == c_balance_before
                )
            )
        );
    }

