contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // _minSum: MinSum to set; _deposit: amount to deposit into c; _collect: amount to attempt to collect
    function run(uint _minSum, uint _deposit, uint _collect) public payable {
        // ensure this test contract has enough balance to fund the deposit
        require(address(this).balance >= _deposit);

        // initialize c (allowed once)
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // perform a deposit from this contract into c
        c.Deposit{value: _deposit}();

        // observe pre-call values
        uint bal_before = c.balances(address(this));
        uint my_before = address(this).balance;
        uint c_before = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(_collect) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-call values
        uint bal_after = c.balances(address(this));
        uint my_after = address(this).balance;
        uint c_after = address(c).balance;

        // If Collect succeeded then the caller (this contract) must receive exactly the decrease
        // in its recorded balance: bal_before == bal_after + amt_received, and my_after == my_before + amt_received,
        // where amt_received = my_after - my_before. If Collect reverted then nothing changed.
        // This asserts that when Collect does not revert, balances decreases and this contract's ETH increases by the same positive amount.
        assert(
            reverted
            ? (bal_after == bal_before && my_after == my_before && c_after == c_before)
            : (
                // amount received (derived from observed ETH) must be > 0
                my_after > my_before
                // recorded balance decreased by the same amount
                && bal_before == bal_after + (my_after - my_before)
                // contract's balance decreased by same amount
                && c_before == c_after + (my_after - my_before)
            )
        );
    }

    // receive to allow this test contract to get ETH back from c
    receive() external payable {}
}
